 void UpdateSmith(float dt,float raw){if(smith==null)return;dt=Mathf.Min(raw,.1f);reachTime=Mathf.Max(0,reachTime-dt);movement=new Vector2((heldKeys.Contains("KeyD")||heldKeys.Contains("ArrowRight")?1:0)-(heldKeys.Contains("KeyA")||heldKeys.Contains("ArrowLeft")?1:0),(heldKeys.Contains("KeyW")||heldKeys.Contains("ArrowUp")?1:0)-(heldKeys.Contains("KeyS")||heldKeys.Contains("ArrowDown")?1:0));if(touchMoving)movement=Vector2.ClampMagnitude((touchLast-touchOrigin)*5,1)*new Vector2(1,-1);if(movement.sqrMagnitude>.01f&&!swinging){workFocus=false;if(destinationAction=="begin"&&route!=null)Send("settled");route=null;destination="";}
  Vector3 direction;if(route!=null&&routeIndex<route.Length){direction=route[routeIndex]-smith.position;direction.y=0;if(direction.magnitude<.14f){routeIndex++;if(routeIndex>=route.Length){route=null;Nearby();if(destination!=""){nearby=destination;var action=destinationAction;destination="";if(action=="begin")BeginSwing();else if(action=="focus")FaceStation("anvil");else if(action=="strike")TryStrike();else Interact();}}direction=Vector3.zero;}else direction.Normalize();}else{var forward=Quaternion.Euler(0,orbitYaw,0)*Vector3.forward;direction=forward*movement.y+Vector3.Cross(Vector3.up,forward)*movement.x;direction=Vector3.ClampMagnitude(direction,1);}
  if(swinging||state?.ended==true)direction=Vector3.zero;float speed=heldKeys.Contains("ShiftLeft")?3.8f:2.15f;var next=smith.position+direction*speed*dt;var px=new Vector3(next.x,0,smith.position.z);if(Walkable(px))smith.position=px;var pz=new Vector3(smith.position.x,0,next.z);if(Walkable(pz))smith.position=pz;if(direction.sqrMagnitude>.01f)smith.rotation=Quaternion.Slerp(smith.rotation,Quaternion.LookRotation(direction),1-Mathf.Exp(-dt*12));walkSpeed=Mathf.Lerp(walkSpeed,direction.magnitude*(speed>3?2:1),1-Mathf.Exp(-dt*10));smithAnimator.SetFloat("Speed",walkSpeed);Nearby();
  if(nearby=="lantern"&&Vector3.Distance(smith.position,approaches["lantern"])<.4f&&heldKeys.Contains("KeyE")){endHold+=raw;if(endHold>=1.2f){endHold=0;heldKeys.Remove("KeyE");Send("command",0,"end");}}else endHold=0;
  contextClock+=dt;if(contextClock>.12f){contextClock=0;UpdateContext();}
 }
