 void UpdateContext(){string hint="WASD to walk · Drag to look · Walk up to a station";if(state?.ended==true)hint="Seven days. Your masterwork is ready.";else if(nearby=="shop"&&state?.offers!=null&&state.offers.Length>0){shopIndex%=state.offers.Length;var offer=state.offers[shopIndex];hint="Q / R  Browse · "+offer.label+" · "+offer.price+" gold · E  Buy";}else if(nearby=="lantern")hint=state?.day==7?"Hold E to finish your seventh day":"Only rack knives stay overnight · Hold E to end day";else if(nearby!=""){if(carriedId>=0)hint=nearby=="furnace"?"E  Place the blank in the fire":nearby=="anvil"?"E  Lay the knife on the anvil":nearby=="rack"?"E  Keep this knife overnight":nearby=="sell"?"E  Sell the knife on the scale":"E  Put down the knife";else{bool has=false;if(state!=null)foreach(var k in state.knives)if(k.place==nearby)has=true;hint=nearby=="anvil"&&has?"SPACE  Swing the hammer · E  Pick up · F  Flow":has?"E  Pick up a knife · Q / R  Choose another":"No knife here. Find a blank in the crate.";}}if(carriedId>=0&&bodies.TryGetValue(carriedId,out var held)){if(nearby=="sell")hint="E  Sell for "+held.knife.saleValue+" gold · Removes knife from your score";hint=held.knife.displayName+" · "+hint;}if(Screen.width<700){hint=hint.Replace("WASD to walk · Drag to look · Walk up to a station","Hold the pad to walk · Drag right to look").Replace("SPACE  Swing the hammer · E  Pick up · F  Flow","Hammer to strike · Handle to pick up · Flow").Replace("E  ","Handle: ").Replace("Hold E to end day","Hold Handle to end day").Replace("Hold E to finish your seventh day","Hold Handle to finish your seventh day").Replace("Q / R  Choose another", "Hold to pick up");}if(hint!=lastContext){lastContext=hint;Send("context",carriedId,hint);}Send("position",carriedId,nearby,smith.position.x,smith.position.z);}
 void UpdateSmithCamera(float dt){if(smith==null)return;bool phone=Screen.width<700;var rotation=Quaternion.Euler(orbitPitch,orbitYaw,0);var look=smith.position+Vector3.up*1.4f+rotation*Vector3.forward*1.3f;var desired=smith.position+Vector3.up*1.4f+rotation*new Vector3(.55f,0,phone?-6.8f:-6);
  float fov=phone?58:45;
  if(workFocus){look=new Vector3(.05f,1.05f,-.4f);desired=phone?new Vector3(1.0f,6.9f,-6.4f):new Vector3(1.3f,4.25f,-4.1f);fov=phone?58:47;}
  desired.x=Mathf.Clamp(desired.x,-8.2f,8.2f);desired.z=Mathf.Clamp(desired.z,-8.6f,6.5f);float ease=reduced?1:1-Mathf.Exp(-dt*5);cameraHome=Vector3.Lerp(cameraHome,desired,ease);cameraLook=Vector3.Lerp(cameraLook,look,ease);cam.fieldOfView=Mathf.Lerp(cam.fieldOfView,fov,ease);cam.transform.position=cameraHome;cam.transform.LookAt(cameraLook);
 }
 void PlayerPointer(ForgePointer p){if(smith==null||state?.ended==true)return;if(p.phase=="down"){pointerStarted=Time.unscaledTime;touchOrigin=touchLast=new Vector2(p.x,p.y);touchMoving=false;Send("gesture");}else if(p.phase=="move"){var at=new Vector2(p.x,p.y);if(Vector2.Distance(at,touchOrigin)>.015f){{workFocus=false;orbitYaw+=(at.x-touchLast.x)*190;orbitPitch=Mathf.Clamp(orbitPitch+(at.y-touchLast.y)*100,12,48);touchLast=at;touchMoving=false;}}}else if(p.phase=="up"){bool tap=Vector2.Distance(new Vector2(p.x,p.y),touchOrigin)<.015f;touchMoving=false;movement=Vector2.zero;if(tap&&workFocus&&p.x>.16f&&p.x<.84f&&p.y>.3f&&p.y<.77f){TryStrike();return;}if(tap){var ray=cam.ViewportPointToRay(new Vector3(p.x,1-p.y));string best="";float score=.95f;foreach(var spot in spots){var along=Vector3.Dot(spot.Value-ray.origin,ray.direction);if(along<0)continue;float d=Vector3.Distance(ray.GetPoint(along),spot.Value);if(d<score){score=d;best=spot.Key;}}if(best!=""){if(nearby==best){if(best=="anvil"&&carriedId<0&&Time.unscaledTime-pointerStarted<.45f)TryStrike();else if(best=="lantern"){Send("spot",0,"lantern");}else Interact();}else GoTo(best);}}}else if(p.phase=="cancel"){touchMoving=false;movement=Vector2.zero;}}
 void GoTo(string station,string action="interact"){destinationAction=action;var goal=approaches[station];var start=smith.position;var path=new List<Vector3>();bool crosses=false;for(int i=1;i<=20;i++)if(!Walkable(Vector3.Lerp(start,goal,i/20f))){crosses=true;break;}if(crosses){float side=Mathf.Abs(start.x-6)+Mathf.Abs(goal.x-6)<Mathf.Abs(start.x+6)+Mathf.Abs(goal.x+6)?6:-6;float fromZ=start.z<1.2f?-1.8f:4.25f;float toZ=goal.z<1.2f?-1.8f:4.25f;path.Add(new Vector3(start.x,0,fromZ));path.Add(new Vector3(side,0,fromZ));path.Add(new Vector3(side,0,toZ));path.Add(new Vector3(goal.x,0,toZ));}path.Add(goal);route=path.ToArray();routeIndex=0;destination=station;}
